import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"62、【小過】 艮下震上","description":"橫渠易說 - 62、【小過】 艮下震上","frontmatter":{"title":"62、【小過】 艮下震上","description":"橫渠易說 - 62、【小過】 艮下震上"},"headers":[],"relativePath":"classics/hengqu/064.md","filePath":"classics/hengqu/064.md"}'),l={name:"classics/hengqu/064.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_62、【小過】-艮下震上" tabindex="-1">62、【小過】 艮下震上 <a class="header-anchor" href="#_62、【小過】-艮下震上" aria-label="Permalink to “62、【小過】 艮下震上”">​</a></h1><h3 id="彖曰-小過-小者過而亨也-過以利貞-與時行也。柔得中-是以小事吉也-剛失位而不中-是以不可大事也。有飛鳥之象焉-飛鳥遺之音-不宜上宜下大吉-上逆而下順也。" tabindex="-1">彖曰：小過，小者過而亨也，過以利貞，與時行也。柔得中，是以小事吉也；剛失位而不中，是以不可大事也。有飛鳥之象焉，“飛鳥遺之音，不宜上宜下大吉”，上逆而下順也。 <a class="header-anchor" href="#彖曰-小過-小者過而亨也-過以利貞-與時行也。柔得中-是以小事吉也-剛失位而不中-是以不可大事也。有飛鳥之象焉-飛鳥遺之音-不宜上宜下大吉-上逆而下順也。" aria-label="Permalink to “彖曰：小過，小者過而亨也，過以利貞，與時行也。柔得中，是以小事吉也；剛失位而不中，是以不可大事也。有飛鳥之象焉，“飛鳥遺之音，不宜上宜下大吉”，上逆而下順也。”">​</a></h3><p>時宜用過，雖過正也。 失其所安者，必矯其所為以求安，過於自大，其勢必危，過於自損，可以獲吉，故曰“上逆而下順，飛鳥之象”。</p><h3 id="象曰-山上有雷-小過-君子以行過乎恭-喪過乎哀-用過乎儉。" tabindex="-1">象曰：山上有雷，小過，君子以行過乎恭，喪過乎哀，用過乎儉。 <a class="header-anchor" href="#象曰-山上有雷-小過-君子以行過乎恭-喪過乎哀-用過乎儉。" aria-label="Permalink to “象曰：山上有雷，小過，君子以行過乎恭，喪過乎哀，用過乎儉。”">​</a></h3><p>過恭、哀、儉，皆宜下之義。</p><h3 id="初六-飛鳥以兇。-象曰-飛鳥以兇-不可如何也。" tabindex="-1">初六，飛鳥以兇。 象曰：“飛鳥以兇”，不可如何也。 <a class="header-anchor" href="#初六-飛鳥以兇。-象曰-飛鳥以兇-不可如何也。" aria-label="Permalink to “初六，飛鳥以兇。 象曰：“飛鳥以兇”，不可如何也。”">​</a></h3><h3 id="六二-過其祖-遇其妣-不及其君-遇其臣-無咎。-象曰-不及其君-臣不可過也。" tabindex="-1">六二，過其祖，遇其妣，不及其君，遇其臣，無咎。 象曰：“不及其君”，臣不可過也。 <a class="header-anchor" href="#六二-過其祖-遇其妣-不及其君-遇其臣-無咎。-象曰-不及其君-臣不可過也。" aria-label="Permalink to “六二，過其祖，遇其妣，不及其君，遇其臣，無咎。 象曰：“不及其君”，臣不可過也。”">​</a></h3><p>與其上比於陽，不若下遇於陰，與其上合於五，不若退附於初，宜下之義也。無應於上，故能免咎。臣居己下，猶不可過，況其他乎!</p><h3 id="九三-弗過防之-從或戕之-兇。-象曰-從或戕之-兇如何也" tabindex="-1">九三，弗過防之，從或戕之，兇。 象曰：“從或戕之”，兇如何也! <a class="header-anchor" href="#九三-弗過防之-從或戕之-兇。-象曰-從或戕之-兇如何也" aria-label="Permalink to “九三，弗過防之，從或戕之，兇。 象曰：“從或戕之”，兇如何也!”">​</a></h3><p>居陽以剛而應於上，為眾所疾，非過為防慎，人或戕之，兇之甚也。</p><h3 id="九四-無咎-弗過遇之-往厲必戒-勿用永貞。-象曰-弗過遇之-位不當也-往厲必戒-終不可長也。" tabindex="-1">九四，無咎，弗過遇之，往厲必戒，勿用永貞。 象曰：“弗過遇之”，位不當也；“往厲必戒”，終不可長也。 <a class="header-anchor" href="#九四-無咎-弗過遇之-往厲必戒-勿用永貞。-象曰-弗過遇之-位不當也-往厲必戒-終不可長也。" aria-label="Permalink to “九四，無咎，弗過遇之，往厲必戒，勿用永貞。 象曰：“弗過遇之”，位不當也；“往厲必戒”，終不可長也。”">​</a></h3><p>道非剛亢，故無咎，有應於下，故曰“弗過遇之”。過此以往，難無以除，故危而必戒；不可當然，故勿用永貞。一雲：九四以陽居陰而乘九三之剛，非其過也，乃適與之遇爾，故無咎；若率是而往， 必危以為戒，終不可久，故勿用永貞，當思奮爾。</p><h3 id="六五-密雲不雨-自我西郊。公弋取彼在穴。-象曰-密雲不雨-已上也。" tabindex="-1">六五，密雲不雨，自我西郊。公弋取彼在穴。 象曰：“密雲不雨”，已上也。 <a class="header-anchor" href="#六五-密雲不雨-自我西郊。公弋取彼在穴。-象曰-密雲不雨-已上也。" aria-label="Permalink to “六五，密雲不雨，自我西郊。公弋取彼在穴。 象曰：“密雲不雨”，已上也。”">​</a></h3><p>不能畜剛止健。凡言“自我西郊”，進而不已也。柔得中，小事吉，故曰“公弋取彼在穴”，非及物之功，且不能摧敵止暴也。三止於下，隱伏之象，故曰“在穴”。小過有飛鳥之象，故因曰“取彼在穴”。雨必蒸聚，自下而上，則其潤澤周普，今自西而東，趨其所應，其施未光也。“已上”亦尚往之義。</p><h3 id="上六-弗遇過之-飛鳥離之-兇-是謂災眚。-象曰-弗遇過之-已亢也。" tabindex="-1">上六，弗遇過之，飛鳥離之，兇，是謂災眚。 象曰：“弗遇過之”，已亢也。 <a class="header-anchor" href="#上六-弗遇過之-飛鳥離之-兇-是謂災眚。-象曰-弗遇過之-已亢也。" aria-label="Permalink to “上六，弗遇過之，飛鳥離之，兇，是謂災眚。 象曰：“弗遇過之”，已亢也。”">​</a></h3><p>不宜上而上，乃自取之災也。</p>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
